import { format, subDays } from 'date-fns';
import { forwardFillValues } from '../utils/metricUtils';
import { evaluateImputedMetric } from '../utils/imputedMetricsEvaluator';

export const loadDailyMetrics = (currentDate, metricDefinitions) => {
  const storedDailyMetrics = localStorage.getItem(format(currentDate, 'yyyy-MM-dd'));
  let parsedDailyMetrics = storedDailyMetrics ? JSON.parse(storedDailyMetrics) : {};
  
  const imputedMetricDefs = metricDefinitions.filter(m => m.isImputed);
  if (imputedMetricDefs.length > 0) {
    const historicalData = getHistoricalData(currentDate);
    
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const currentDateStart = new Date(currentDate);
    currentDateStart.setHours(0, 0, 0, 0);

    if (currentDateStart <= today) {
      parsedDailyMetrics = computeImputedMetrics(
        parsedDailyMetrics,
        imputedMetricDefs,
        metricDefinitions,
        historicalData
      );
    }
  }

  return parsedDailyMetrics;
};

export const saveDailyMetrics = (date, metrics) => {
  localStorage.setItem(format(date, 'yyyy-MM-dd'), JSON.stringify(metrics));
};

export const computeImputedMetrics = (baseMetrics, imputedMetricDefs, allMetricDefs, historicalData) => {
  const newMetrics = { ...baseMetrics };
  
  // Forward fill all non-imputed metrics
  const filledMetrics = {};
  allMetricDefs
    .filter(m => !m.isImputed)
    .forEach(m => {
      const values = forwardFillValues(historicalData, m.name);
      filledMetrics[m.name] = values[values.length - 1];
    });

  // Create a get function that combines base metrics with filled metrics
  const get = (metric) => {
    if (baseMetrics[metric] !== null && !isNaN(baseMetrics[metric])) {
      return baseMetrics[metric];
    }
    return filledMetrics[metric];
  };

  // Compute each imputed metric
  imputedMetricDefs.forEach(metricDef => {
    const imputedValue = evaluateImputedMetric(metricDef.expression, get);
    if (imputedValue !== null) {
      newMetrics[metricDef.name] = imputedValue;
    }
  });

  return newMetrics;
};

const getHistoricalData = (currentDate) => {
  const historicalData = [];
  for (let i = 30; i >= 0; i--) {
    const date = subDays(currentDate, i);
    const dateStr = format(date, 'yyyy-MM-dd');
    const dayData = localStorage.getItem(dateStr);
    if (dayData) {
      historicalData.push({ date: dateStr, ...JSON.parse(dayData) });
    }
  }
  return historicalData;
};
