import { format } from 'date-fns';

export const getDelayedCorrelationData = (xMetric, yMetric, delay) => {
  const data = [];
  
  // Collect all date-based entries
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (key.match(/^\d{4}-\d{2}-\d{2}$/)) {
      const dayData = JSON.parse(localStorage.getItem(key));
      if (dayData[xMetric] != null && dayData[yMetric] != null) {
        data.push({
          date: key,
          x: parseFloat(dayData[xMetric]),
          y: parseFloat(dayData[yMetric])
        });
      }
    }
  }
  
  // Sort data by date
  const sortedData = data.sort((a, b) => a.date.localeCompare(b.date));
  
  if (delay === 0) return sortedData;

  // Create a map of dates to values for both metrics
  const xValues = new Map();
  const yValues = new Map();
  
  sortedData.forEach(point => {
    const date = new Date(point.date);
    xValues.set(date.getTime(), point.x);
    yValues.set(date.getTime(), point.y);
  });

  // Create delayed correlation data
  const delayedData = [];
  const dayInMs = 24 * 60 * 60 * 1000;
  
  xValues.forEach((xValue, xDate) => {
    const yDate = xDate + (delay * dayInMs);
    const yValue = yValues.get(yDate);
    
    if (yValue !== undefined) {
      delayedData.push({
        date: new Date(xDate).toISOString().split('T')[0],
        x: xValue,
        y: yValue
      });
    }
  });

  return delayedData;
};

export const calculateCorrelation = (data) => {
  if (data.length < 2) return null;

  const n = data.length;
  let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0, sumY2 = 0;

  data.forEach(point => {
    sumX += point.x;
    sumY += point.y;
    sumXY += point.x * point.y;
    sumX2 += point.x * point.x;
    sumY2 += point.y * point.y;
  });

  const numerator = (n * sumXY) - (sumX * sumY);
  const denominator = Math.sqrt((n * sumX2 - sumX * sumX) * (n * sumY2 - sumY * sumY));

  return denominator === 0 ? 0 : numerator / denominator;
};
