import React, { useState, useEffect, useRef } from 'react';
import { ScatterChart, Scatter, XAxis, YAxis, CartesianGrid, Tooltip, Label } from 'recharts';
import { getAllMetricsData, calculateCorrelation, getDelayedCorrelationData } from '../utils/correlationUtils';
import { calculateYAxisDomain } from '../utils/plotUtils';

const MetricsCorrelation = () => {
  const [metrics, setMetrics] = useState([]);
  const [xMetric, setXMetric] = useState('');
  const [yMetric, setYMetric] = useState('');
  const [correlationData, setCorrelationData] = useState([]);
  const [timeDelay, setTimeDelay] = useState(0);
  const [containerWidth, setContainerWidth] = useState(0);
  const plotContentRef = useRef(null);
  
  useEffect(() => {
    const storedMetrics = localStorage.getItem('metrics');
    if (storedMetrics) {
      const parsedMetrics = JSON.parse(storedMetrics);
      setMetrics(parsedMetrics);
      if (parsedMetrics.length > 1) {
        setXMetric(parsedMetrics[0].name);
        setYMetric(parsedMetrics[1].name);
      }
    }
  }, []);

  useEffect(() => {
    if (xMetric && yMetric) {
      const data = getDelayedCorrelationData(xMetric, yMetric, timeDelay);
      setCorrelationData(data);
    }
  }, [xMetric, yMetric, timeDelay]);

  const handleResize = () => {
    if (plotContentRef.current) {
      setContainerWidth(plotContentRef.current.clientWidth - 40); // Subtract padding/margins
    }
  };

  useEffect(() => {
    handleResize(); // Initial width calculation
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return (
    <div className="plot-container">
      <h2 className="section-title">Metrics Correlation</h2>
      
      <div className="plot-controls">
        <select 
          value={xMetric} 
          onChange={(e) => setXMetric(e.target.value)}
          className="metric-select"
        >
          <option value="">Select X Metric</option>
          {metrics.map(metric => (
            <option key={metric.name} value={metric.name}>
              {metric.name} ({metric.unit})
            </option>
          ))}
        </select>

        <select 
          value={yMetric} 
          onChange={(e) => setYMetric(e.target.value)}
          className="metric-select"
        >
          <option value="">Select Y Metric</option>
          {metrics.map(metric => (
            <option key={metric.name} value={metric.name}>
              {metric.name} ({metric.unit})
            </option>
          ))}
        </select>
        <div className="time-delay-control">
          <label htmlFor="time-delay">Time Delay (days):</label>
          <input
            type="number"
            id="time-delay"
            min="-30"
            max="30"
            value={timeDelay}
            onChange={(e) => setTimeDelay(parseInt(e.target.value) || 0)}
            className="time-delay-input"
          />
        </div>
      </div>

      <div className="correlation-stats">
        {correlationData.length > 1 && (
          <>
            <div className="stat-item">
              <span className="stat-label">Correlation (r):</span>
              <span className="stat-value">{calculateCorrelation(correlationData).toFixed(3)}</span>
            </div>
            <div className="stat-item">
              <span className="stat-label">R²:</span>
              <span className="stat-value">{Math.pow(calculateCorrelation(correlationData), 2).toFixed(3)}</span>
            </div>
          </>
        )}
      </div>
      <div className="plot-content" ref={plotContentRef}>
        {correlationData.length > 0 ? (
          <ScatterChart
            width={containerWidth}
            height={400}
            margin={{ top: 20, right: 30, bottom: 30, left: 40 }}
          >
            <CartesianGrid />
            <XAxis 
              type="number" 
              dataKey="x" 
              name={xMetric}
              domain={['auto', 'auto']}
            >
              <Label value={xMetric} offset={-10} position="insideBottom" />
            </XAxis>
            <YAxis 
              type="number" 
              dataKey="y" 
              name={yMetric}
              domain={['auto', 'auto']}
            >
              <Label value={yMetric} angle={-90} position="insideLeft" offset={10} />
            </YAxis>
            <Tooltip 
              cursor={{ strokeDasharray: '3 3' }}
              content={({ payload }) => {
                if (!payload || !payload[0]) return null;
                const data = payload[0].payload;
                const xDate = new Date(data.date);
                const yDate = new Date(xDate.getTime() + (timeDelay * 24 * 60 * 60 * 1000));
                return (
                  <div className="custom-tooltip">
                    <p>{`${xMetric}: ${data.x.toFixed(2)} (${xDate.toLocaleDateString()})`}</p>
                    <p>{`${yMetric}: ${data.y.toFixed(2)} (${yDate.toLocaleDateString()})`}</p>
                  </div>
                );
              }}
            />
            <Scatter 
              data={correlationData} 
              fill="#8884d8"
              line={{ stroke: '#ff7300', strokeWidth: 1 }}
              lineType="fitting"
            />
          </ScatterChart>
        ) : (
          <div className="no-data-message">
            Select two metrics to see their correlation
          </div>
        )}
      </div>
    </div>
  );
};

export default MetricsCorrelation;
