import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { validateMetricReferences } from '../utils/imputedMetricsEvaluator';

const MetricManager = () => {
  const [metrics, setMetrics] = useState([]);
  const [newMetric, setNewMetric] = useState({ 
    name: '', 
    unit: '', 
    timeOfDay: 'AM',
    isImputed: false,
    expression: `(get) => {
  // Convert weight from kg to lbs
  return get('weight') * 2.20462;
}`
  });
  const [editingIndex, setEditingIndex] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    loadMetrics();
  }, []);

  const loadMetrics = () => {
    const storedMetrics = localStorage.getItem('metrics');
    if (storedMetrics) {
      setMetrics(JSON.parse(storedMetrics));
    }
  };

  const saveMetrics = (updatedMetrics) => {
    localStorage.setItem('metrics', JSON.stringify(updatedMetrics));
    setMetrics(updatedMetrics);
  };

  const validateExpression = (expression) => {
    try {
      if (!expression.trim()) {
        return { isValid: false, error: 'Expression cannot be empty' };
      }

      // Try to create a function from the expression
      new Function('return ' + expression)();
      return { isValid: true };
    } catch (error) {
      return { isValid: false, error: `Invalid expression: ${error.message}` };
    }
  };

  const validateMetricFunction = (expression) => {
    try {
      // Create a dummy get function for validation
      const get = (metric) => 0;
      
      // Try to create a function from the expression
      const fn = new Function('return ' + expression)();
      
      // Test if it's actually a function
      if (typeof fn !== 'function') {
        return { isValid: false, error: 'Expression must evaluate to a function' };
      }
      
      // Test if the function accepts the get parameter and returns a number
      const testResult = fn(get);
      if (testResult !== null && typeof testResult !== 'number') {
        return { isValid: false, error: 'Function must return a number or null' };
      }
      return { isValid: true };
    } catch (error) {
      return { isValid: false, error: 'Invalid function: ' + error.message };
    }
  };

  const handleAddOrUpdateMetric = (e) => {
    e.preventDefault();
    
    if (!newMetric.name || !newMetric.unit) {
      alert('Name and unit are required');
      return;
    }

    if (newMetric.isImputed) {
      const funcValidation = validateMetricFunction(newMetric.expression);
      
      if (!funcValidation.isValid) {
        alert(funcValidation.error);
        return;
      }

      // Then validate metric references
      const availableMetrics = metrics
        .filter(m => !m.isImputed || m.name === newMetric.name)
        .map(m => m.name);
      
      const refValidation = validateMetricReferences(newMetric.expression, availableMetrics);
      
      if (!refValidation.isValid) {
        alert(refValidation.error);
        return;
      }
    }
    
    let updatedMetrics;
    if (editingIndex !== null) {
      updatedMetrics = metrics.map((metric, index) =>
        index === editingIndex ? newMetric : metric
      );
    } else {
      updatedMetrics = [...metrics, newMetric];
    }
    saveMetrics(updatedMetrics);
    setNewMetric({ name: '', unit: '', timeOfDay: 'AM' });
    setEditingIndex(null);
  };

  const handleDeleteMetric = (index) => {
    const updatedMetrics = metrics.filter((_, i) => i !== index);
    saveMetrics(updatedMetrics);
  };

  const handleEditMetric = (index) => {
    setNewMetric(metrics[index]);
    setEditingIndex(index);
  };

  return (
    <div className="metric-manager">
      <h2 className="section-title">Manage Metrics</h2>
      <form onSubmit={handleAddOrUpdateMetric}>
        <div className="input-container">
          <label htmlFor="metric-name">Metric Name:</label>
          <input
            id="metric-name"
            type="text"
            value={newMetric.name}
            onChange={(e) => setNewMetric({ ...newMetric, name: e.target.value })}
            required
          />
        </div>
        <div className="input-container">
          <label htmlFor="metric-unit">Unit:</label>
          <input
            id="metric-unit"
            type="text"
            value={newMetric.unit}
            onChange={(e) => setNewMetric({ ...newMetric, unit: e.target.value })}
            required
          />
        </div>
        <div className="input-container">
          <label htmlFor="metric-time">Time of Day:</label>
          <select
            id="metric-time"
            value={newMetric.timeOfDay}
            onChange={(e) => setNewMetric({ ...newMetric, timeOfDay: e.target.value })}
            disabled={newMetric.isImputed}
          >
            <option value="AM">AM</option>
            <option value="PM">PM</option>
          </select>
        </div>
        <div className="input-container">
          <label>
            <input
              type="checkbox"
              checked={newMetric.isImputed}
              onChange={(e) => setNewMetric({ ...newMetric, isImputed: e.target.checked })}
            />
            Imputed Metric
          </label>
        </div>
        {newMetric.isImputed && (
          <div className="input-container expression-editor">
            <label htmlFor="metric-expression">Expression:</label>
            <textarea
              name="metric-expression"
              value={newMetric.expression}
              onChange={(e) => setNewMetric({ ...newMetric, expression: e.target.value })}
              placeholder="Enter your function here..."
              rows={6}
              style={{
                width: '100%',
                fontFamily: 'monospace',
                padding: '8px',
                resize: 'vertical'
              }}
            />
          </div>
        )}
        <button type="submit">{editingIndex !== null ? 'Update Metric' : 'Add Metric'}</button>
        {editingIndex !== null && (
          <button type="button" onClick={() => {
            setNewMetric({ name: '', unit: '', timeOfDay: 'AM' });
            setEditingIndex(null);
          }}>Cancel Edit</button>
        )}
      </form>
      <div className="metrics-list">
        <h3 className="section-title">Current Metrics</h3>
        {metrics.map((metric, index) => (
          <div key={index} className="metric-item">
            <span>
              {metric.name} ({metric.unit}) {!metric.isImputed && `- ${metric.timeOfDay}`}
              {metric.isImputed && <span className="imputed-badge">Imputed</span>}
              {metric.isImputed && <div className="expression-text">Expression: {metric.expression}</div>}
            </span>
            <div>
              <button onClick={() => handleEditMetric(index)}>Edit</button>
              <button onClick={() => handleDeleteMetric(index)}>Delete</button>
            </div>
          </div>
        ))}
      </div>
      <button onClick={() => navigate('/')} className="back-to-log-btn">
        Back to Log
      </button>
    </div>
  );
};

export default MetricManager;
