import React, { useState, useCallback } from 'react';
import { LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Legend, Tooltip, ReferenceLine, Label, Cell } from 'recharts';
import { format, parse } from 'date-fns';

const MetricsChart = React.memo(({
  data, 
  chartType, 
  selectedMetric, 
  timeAxisMode,
  containerWidth,
  periodicityK,
  periodicityN,
  yAxisDomain,
  lineColor = '#8884d8',
  lineWidth = 2
}) => {
  const [verticalLineX, setVerticalLineX] = useState(null);
  const [tooltipData, setTooltipData] = useState(null);

  const handleChartClick = useCallback((e) => {
    if (chartType !== 'line' || !e || !e.activeLabel) return;
    
    // Use the chart's internal coordinates directly
    const xValue = e.chartX;
    
    // Get the clicked point's value
    const clickX = timeAxisMode === 'periodic' ? 
      parseInt(e.activeLabel) : // For periodic mode, activeLabel is the period day
      e.activeLabel; // For linear mode, use the date directly
    
    if (timeAxisMode === 'periodic') {
      // For periodic mode, find all values for this day across periods
      const dayValues = data.filter(item => 
        item.periodDay === clickX && 
        item[selectedMetric] !== null && 
        item[selectedMetric] !== undefined
      );
      
      if (dayValues.length > 0) {
        setVerticalLineX(clickX);
        setTooltipData(dayValues.map(item => ({
          period: item.periodNumber + 1,
          value: item[selectedMetric]
        })));
      }
    } else {
      // For linear mode, find the exact point
      const point = data.find(d => new Date(d.date).getTime() === clickX);
      if (point) {
        setVerticalLineX(new Date(point.date).getTime());
        setTooltipData([{
          date: point.date,
          value: point[selectedMetric]
        }]);
      }
    }
  }, [data, chartType, timeAxisMode, containerWidth, periodicityK, selectedMetric]);

  if (data.length === 0) {
    return (
      <div style={{
        width: containerWidth || window.innerWidth - 40,
        height: 400,
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        border: '1px solid #ccc',
        borderRadius: '4px',
        color: '#666'
      }}>
        No data available
      </div>
    );
  }

  if (chartType === 'line') {
    return (
      <LineChart 
        width={containerWidth || window.innerWidth - 40}
        height={400}
        data={data}
        margin={{ top: 5, right: 20, left: 5, bottom: 5 }}
        onClick={handleChartClick}
      >
        <XAxis 
          dataKey={timeAxisMode === 'periodic' ? 'periodDay' : 'timestamp'}
          tickFormatter={timeAxisMode === 'periodic' ? 
            (value) => `Day ${value}` : 
            (timestamp) => {
              try {
                const date = new Date(timestamp);
                return format(date, 'MMM dd');
              } catch (error) {
                console.error('Error formatting tick:', error);
                return '';
              }
            }
          }
          type="number"
          domain={timeAxisMode === 'periodic' ? [1, periodicityK] : ['dataMin', 'dataMax']}
          scale={timeAxisMode === 'periodic' ? 'linear' : 'time'}
        />
        <YAxis 
          domain={yAxisDomain} 
          allowDataOverflow={true}
          tickFormatter={(value) => {
            if (Math.abs(value) >= 1000) {
              return (value / 1000).toFixed(1) + 'k';
            } else if (Math.abs(value) < 0.01) {
              return value.toExponential(1);
            } else {
              return Number(value.toFixed(2));
            }
          }}
        />
        <CartesianGrid strokeDasharray="3 3" />
        {timeAxisMode === 'periodic' ? 
          [...new Set(data.map(item => item.periodNumber))].map((period, index) => (
            <Line
              key={period}
              type="monotone"
              data={data.filter(item => item.periodNumber === period)}
              dataKey={selectedMetric}
              name={`Period ${period + 1}`}
              stroke={`hsl(${(index * 360) / periodicityN}, 70%, 50%)`}
              connectNulls={true}
              dot={{
                r: 4,
                style: { cursor: 'pointer' }
              }}
              activeDot={{ 
                r: 8,
                style: { cursor: 'pointer' }
              }}
              isAnimationActive={false}
            />
          )) :
          <Line 
            type="monotone" 
            dataKey={selectedMetric} 
            stroke={lineColor}
            strokeWidth={lineWidth}
            connectNulls={true}
            data={data.map(item => ({
              ...item,
              timestamp: new Date(item.date).getTime()
            }))}
            dot={(props) => {
              const { payload, cx, cy, index } = props;
              const pointId = `point-${payload.date}-${payload.periodNumber || 0}-${index}`;
              return (
                <circle 
                  key={pointId}
                  id={pointId}
                  cx={cx} 
                  cy={cy} 
                  r={4}
                  fill="#8884d8"
                  stroke="none"
                  style={{ cursor: 'pointer' }}
                />
              );
            }}
            activeDot={(props) => {
              const { payload, cx, cy, index } = props;
              const pointId = `active-point-${payload.date}-${payload.periodNumber || 0}-${index}`;
              return (
                <circle 
                  key={pointId}
                  id={pointId}
                  cx={cx} 
                  cy={cy} 
                  r={8}
                  fill="#8884d8"
                  stroke="white"
                  strokeWidth={2}
                  style={{ cursor: 'pointer' }}
                />
              );
            }}
            isAnimationActive={false}
          />
        }
        <Legend />
        {verticalLineX !== null && (
          <ReferenceLine
            x={verticalLineX}
            stroke="red"
            strokeWidth={2}
            isFront={true}
            label={{
              value: ' ',
              position: 'right',
              content: ({ viewBox }) => (
                // Pass containerWidth to tooltip positioning logic
                <foreignObject
                  x={viewBox.x > containerWidth / 2 ? viewBox.x - 160 : viewBox.x + 10}
                  y={viewBox.y + 10}
                  width={200}
                  height={200}
                >
                  <div style={{ 
                    backgroundColor: 'rgba(255, 255, 255, 1)', 
                    padding: '8px',
                    border: '1px solid #ccc',
                    borderRadius: '4px',
                    boxShadow: '0 2px 4px rgba(0,0,0,0.2)',
                    fontSize: '12px',
                    maxWidth: '140px',
                    position: 'relative',
                    zIndex: 1000
                  }}>
                    {tooltipData && tooltipData.map((item, idx) => (
                      <div key={idx} style={{
                        whiteSpace: 'nowrap',
                        marginBottom: '4px'
                      }}>
                        {timeAxisMode === 'periodic' 
                          ? `Period ${item.period}: ${item.value.toFixed(2)}`
                          : `${format(parse(item.date, 'yyyy-MM-dd', new Date()), 'MMM dd')}: ${item.value.toFixed(2)}`}
                      </div>
                    ))}
                  </div>
                </foreignObject>
              )
            }}
          />
        )}
      </LineChart>
    );
  }

  // For periodic bar chart, calculate means for each day in period
  const getPeriodicBarData = () => {
    const periodicData = Array(periodicityK).fill(null).map((_, day) => ({
      periodDay: day + 1,
      values: [],
      id: `period-${day + 1}`
    }));

    data.forEach((item, idx) => {
      // Only process items with valid period days
      if (item.periodDay && item.periodDay > 0 && item.periodDay <= periodicityK) {
        periodicData[item.periodDay - 1].values.push({
          value: item[selectedMetric],
          id: `bar-${item.periodDay}-${idx}`
        });
      }
    });

    const result = periodicData.map(day => {
      // Only include non-null values in the mean calculation
      const validValues = day.values.filter(val => 
        val.value !== null && 
        !isNaN(val.value) && 
        val.value !== undefined
      );
      
      const mean = validValues.length > 0 
        ? validValues.reduce((sum, val) => sum + val.value, 0) / validValues.length 
        : 0; // Use 0 instead of null
      
      return {
        periodDay: day.periodDay,
        [selectedMetric]: mean,
        id: `period-day-${day.periodDay}`
      };
    });
    
    return result;
  };

  return (
    <BarChart 
      width={containerWidth || window.innerWidth - 40}
      height={400}
      data={timeAxisMode === 'periodic' ? getPeriodicBarData() : data}
      margin={{ top: 5, right: 20, left: 5, bottom: 5 }}
    >
      <XAxis 
        dataKey={timeAxisMode === 'periodic' ? 'periodDay' : 'date'}
        tickFormatter={timeAxisMode === 'periodic' ? 
          (value) => `Day ${value}` : 
          (date) => format(parse(date, 'yyyy-MM-dd', new Date()), 'MMM dd')
        }
        type={timeAxisMode === 'periodic' ? 'number' : 'category'}
        domain={timeAxisMode === 'periodic' ? [0.5, periodicityK + 0.5] : ['dataMin', 'dataMax']}
        ticks={timeAxisMode === 'periodic' ? 
          Array.from({length: periodicityK}, (_, i) => i + 1) : 
          undefined
        }
      />
      <YAxis 
        domain={yAxisDomain} 
        allowDataOverflow={true}
        tickFormatter={(value) => {
          if (Math.abs(value) >= 1000) {
            return (value / 1000).toFixed(1) + 'k';
          } else if (Math.abs(value) < 0.01) {
            return value.toExponential(1);
          } else {
            return Number(value.toFixed(2));
          }
        }}
      />
      <CartesianGrid strokeDasharray="3 3" />
      <Legend />
      /* <Bar 
        dataKey={selectedMetric} 
        fill="#8884d8"
        isAnimationActive={false}
      >
        {timeAxisMode === 'periodic' ? 
          getPeriodicBarData().map((entry, index) => (
            <Cell 
              key={`periodic-cell-${entry.periodDay}-${index}`} 
              fill={`hsl(${(index * 360) / periodicityK}, 70%, 50%)`}
            />
          ))
          :
          data.map((entry, index) => {
            const value = entry[selectedMetric];
            const isValid = value !== null && !isNaN(value) && value !== undefined;
            return isValid ? (
              <Cell 
                key={`linear-cell-${entry.date}-${index}`}
                fill="#8884d8"
              />
            ) : null;
          })
        }
      </Bar> */
    </BarChart>
  );
});

export default MetricsChart;
