import React from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import MetricsLogger from './components/MetricsLogger';
import MetricsPlot from './components/MetricsPlot';
import MetricManager from './components/MetricManager';
import MetricsCorrelation from './components/MetricsCorrelation';
import Navigation from './components/Navigation';
import ClearData from './components/ClearData';
import './BoomerangUI.css';
import './App.css';

function App() {
  return (
    <Router basename={process.env.NODE_ENV === 'production' ? '/daily-log' : ''}>
      <div className="app-container">
        <div className="content-container">
          <Routes>
            <Route path="/" element={<MetricsLogger />} />
            <Route path="/plot" element={<MetricsPlot />} />
            <Route path="/metrics" element={<MetricManager />} />
            <Route path="/clear_data" element={<ClearData />} />
            <Route path="/correlate" element={<MetricsCorrelation />} />
          </Routes>
        </div>
        <Navigation />
      </div>
    </Router>
  );
}

export default App;
