import React from 'react';

const ChartControls = ({ 
  selectedMetric, 
  metrics, 
  chartType, 
  onMetricChange, 
  onChartTypeChange, 
  onCustomizeClick,
  onExportClick 
}) => {
  return (
    <div className="plot-controls">
      <div className="input-container">
        <label htmlFor="metric-select">Metric:</label>
        <select id="metric-select" value={selectedMetric} onChange={onMetricChange}>
          {metrics.map(metric => (
            <option key={metric.name} value={metric.name}>{metric.name}</option>
          ))}
        </select>
        <select value={chartType} onChange={onChartTypeChange}>
          <option value="line">Line Chart</option>
          <option value="bar">Bar Chart</option>
        </select>
      </div>
      <button type="button" onClick={onCustomizeClick}>
        Customize Plot
      </button>
      <button onClick={onExportClick}>
        Export to CSV
      </button>
    </div>
  );
};

export default ChartControls;
