import { parse, format, startOfDay, isAfter, isBefore } from 'date-fns';
import { forwardFillValues } from './metricUtils';
import { evaluateImputedMetric } from './imputedMetricsEvaluator';

export const processMetricData = (sortedData, selectedMetric, selectedMetricDef) => {
  if (selectedMetricDef?.isImputed) {
    return processImputedMetricData(sortedData, selectedMetric, selectedMetricDef);
  }
  return sortedData;
};

export const processImputedMetricData = (sortedData, selectedMetric, selectedMetricDef) => {
  // Forward fill all metrics for imputed calculation
  const filledMetrics = {};
  const allMetrics = new Set();
  
  sortedData.forEach(dataPoint => {
    Object.keys(dataPoint).forEach(metric => {
      if (metric !== 'date' && metric !== selectedMetric) {
        allMetrics.add(metric);
      }
    });
  });

  // First collect all values for each metric
  allMetrics.forEach(metric => {
    filledMetrics[metric] = sortedData.map(item => item[metric]);
  });

  // Then forward fill each metric's values
  allMetrics.forEach(metric => {
    filledMetrics[metric] = forwardFillValues(sortedData, metric);
  });

  // Compute imputed values for each non-future date
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  return sortedData.map((item, index) => {
    const itemDate = parse(item.date, 'yyyy-MM-dd', new Date());
    itemDate.setHours(0, 0, 0, 0);

    if (itemDate <= today) {
      const get = (metric) => filledMetrics[metric]?.[index] ?? null;

      try {
        const imputedValue = evaluateImputedMetric(selectedMetricDef.expression, get);
        
        // Check if the result is a valid number
        const finalValue = (imputedValue !== null && !isNaN(imputedValue)) ? imputedValue : null;
        
        return { 
          ...item, 
          [selectedMetric]: finalValue 
        };
      } catch (error) {
        console.error('Error computing imputed value:', error);
        console.error('Date:', item.date);
        console.error('Expression:', selectedMetricDef.expression);
        return { ...item, [selectedMetric]: null };
      }
    }
    return { ...item, [selectedMetric]: null };
  });
};

export const filterDataByDateRange = (data, dateRangeMode, params) => {
  const { daysToShow, startDate, endDate, keyEvents, selectedStartEvent, selectedEndEvent } = params;

  if (dateRangeMode === 'lastNDays') {
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - daysToShow);
    return data.filter(item => 
      parse(item.date, 'yyyy-MM-dd', new Date()) >= cutoffDate
    );
  }

  if (dateRangeMode === 'keyEvents' && selectedStartEvent && selectedEndEvent) {
    const startEvent = keyEvents.find(e => e.date === selectedStartEvent);
    const endEvent = keyEvents.find(e => e.date === selectedEndEvent);
    
    if (startEvent && endEvent) {
      return data.filter(item => {
        const itemDate = parse(item.date, 'yyyy-MM-dd', new Date());
        const start = parse(startEvent.date, 'yyyy-MM-dd', new Date());
        const end = parse(endEvent.date, 'yyyy-MM-dd', new Date());
        return (itemDate >= start && itemDate <= end);
      });
    }
  }

  const start = startDate ? parse(startDate, 'yyyy-MM-dd', new Date()) : null;
  const end = endDate ? parse(endDate, 'yyyy-MM-dd', new Date()) : new Date();
  
  return data.filter(item => {
    const itemDate = parse(item.date, 'yyyy-MM-dd', new Date());
    return (!start || isAfter(startOfDay(itemDate), startOfDay(start)) || itemDate.getTime() === start.getTime()) &&
           (!end || isBefore(startOfDay(itemDate), startOfDay(end)) || itemDate.getTime() === end.getTime());
  });
};

export const calculateYAxisDomain = (data, selectedMetric, currentDomain) => {
  if (currentDomain[0] !== 'auto' && currentDomain[1] !== 'auto') {
    return currentDomain;
  }

  if (data.length === 0) {
    return currentDomain;
  }

  const values = data.map(item => item[selectedMetric]);
  const minValue = Math.min(...values);
  const maxValue = Math.max(...values);
  const padding = (maxValue - minValue) * 0.1;

  return [
    currentDomain[0] === 'auto' ? minValue - padding : currentDomain[0],
    currentDomain[1] === 'auto' ? maxValue + padding : currentDomain[1]
  ];
};

export const processPeriodicData = (data, periodicityK, periodicityN) => {
  const totalPeriods = Math.ceil(data.length / periodicityK);
  const startPeriod = Math.max(0, totalPeriods - periodicityN);
  
  return data.filter(item => item.periodNumber >= startPeriod);
};
