import React, { useRef } from 'react';
import { Link } from 'react-router-dom';
import { FaTrash } from 'react-icons/fa';
import { exportProfile, importProfile } from '../utils/profileUtils';

const Drawer = ({ isOpen, onClose }) => {
  return (
    <>
      <div className={`drawer-overlay ${isOpen ? 'open' : ''}`} onClick={onClose}></div>
      <div className={`drawer ${isOpen ? 'open' : ''}`}>
        <div className="drawer-header">
          <button className="close-button" onClick={onClose}>&times;</button>
        </div>
        <nav className="drawer-content">
          <Link to="/metrics" className="drawer-item" onClick={onClose}>Manage Metrics</Link>
          <button className="drawer-item" onClick={() => {
            exportProfile();
            onClose();
          }}>Export Profile</button>
          <label className="drawer-item import-profile-label">
            Import Profile
            <input
              type="file"
              accept=".json"
              onChange={async (e) => {
                if (e.target.files?.[0]) {
                  const success = await importProfile(e.target.files[0]);
                  if (success) {
                    window.location.reload();
                  } else {
                    alert('Failed to import profile');
                  }
                }
                onClose();
              }}
              style={{ display: 'none' }}
            />
          </label>
          <Link to="/clear_data" className="drawer-item" onClick={onClose} style={{ color: '#ff3b30' }}>
            <FaTrash style={{ marginRight: '8px' }} />
            Clear All Data
          </Link>
        </nav>
      </div>
    </>
  );
};

export default Drawer;
