export const validateMetricReferences = (expression, availableMetrics) => {
  try {
    // Create a validation get function that tracks metric access
    const accessedMetrics = new Set();
    const get = (metric) => {
      accessedMetrics.add(metric);
      return 0; // Dummy value for validation
    };

    // Create and execute the function
    const fn = new Function('return ' + expression)();
    
    if (typeof fn !== 'function') {
      return { isValid: false, error: 'Expression must be a function' };
    }
    
    // Call the function with get as an argument
    const result = fn(get);
    
    // Check if any accessed metrics don't exist
    const undefinedMetrics = [...accessedMetrics]
      .filter(metric => !availableMetrics.includes(metric));

    return undefinedMetrics.length === 0 
      ? { isValid: true }
      : { 
          isValid: false, 
          error: `Referenced metrics do not exist: ${undefinedMetrics.join(', ')}`
        };
  } catch (error) {
    return { isValid: false, error: 'Error validating metric references: ' + error.message };
  }
};

export const evaluateImputedMetric = (expression, metrics) => {
  try {
    // Create the function from the expression
    const fn = new Function('return ' + expression)();
    
    if (typeof fn !== 'function') {
      console.log('Expression did not evaluate to a function');
      return null;
    }

    // Create the get function that accesses metrics
    const get = (metric) => {
      if (typeof metrics === 'function') {
        return metrics(metric);
      }
      const value = metrics[metric];
      return value === undefined ? null : parseFloat(value);
    };

    // Call the function with our get function
    const result = fn(get);
    
    // Convert to number and validate
    const numericResult = Number(result);
    
    // Check for any irregular values
    if (result === null || 
        result === undefined || 
        isNaN(numericResult) || 
        !isFinite(numericResult) ||
        typeof result === 'boolean' ||
        typeof result === 'string') {
      console.error('Function returned invalid value:', result);
      return null;
    }

    return numericResult;
  } catch (error) {
    console.error('Error evaluating imputed metric:', error);
    return null;
  }
};
