import React from 'react';
import { format, parse } from 'date-fns';

const RangeTypeSelector = ({ 
  dateRangeMode, 
  setDateRangeMode,
  daysToShow,
  handleDaysChange,
  startDate,
  setStartDate,
  endDate, 
  setEndDate,
  keyEvents,
  selectedStartEvent,
  setSelectedStartEvent,
  selectedEndEvent,
  setSelectedEndEvent
}) => {
  return (
    <div>
      <div className="range-type-selector">
        <label>
          <input
            type="radio"
            value="lastNDays"
            checked={dateRangeMode === 'lastNDays'}
            onChange={(e) => setDateRangeMode(e.target.value)}
          />
          Last N Days
        </label>
        <label>
          <input
            type="radio"
            value="custom"
            checked={dateRangeMode === 'custom'}
            onChange={(e) => setDateRangeMode(e.target.value)}
          />
          Custom Date Range
        </label>
        <label>
          <input
            type="radio"
            value="keyEvents"
            checked={dateRangeMode === 'keyEvents'}
            onChange={(e) => setDateRangeMode(e.target.value)}
          />
          Between Key Events
        </label>
      </div>

      {dateRangeMode === 'lastNDays' && (
        <div className="input-container">
          <label htmlFor="days-input">Number of days to display:</label>
          <input
            id="days-input"
            type="number"
            value={daysToShow}
            onChange={handleDaysChange}
            min="1"
            max="365"
            className="input"
          />
        </div>
      )}
      
      {dateRangeMode === 'custom' && (
        <div className="custom-date-range">
          <div className="input-container">
            <label htmlFor="start-date">Start Date:</label>
            <input
              id="start-date"
              type="date"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              className="input"
            />
          </div>
          <div className="input-container">
            <label htmlFor="end-date">End Date:</label>
            <input
              id="end-date"
              type="date"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              className="input"
            />
          </div>
        </div>
      )}
      
      {dateRangeMode === 'keyEvents' && (
        <div className="key-events-range">
          <div className="input-container">
            <label htmlFor="start-event">Start Event:</label>
            <select
              id="start-event"
              value={selectedStartEvent}
              onChange={(e) => setSelectedStartEvent(e.target.value)}
              className="input"
            >
              <option value="">Select start event</option>
              {keyEvents.map(event => (
                <option key={event.date} value={event.date}>
                  {format(parse(event.date, 'yyyy-MM-dd', new Date()), 'MMM dd, yyyy')}: {event.event}
                </option>
              ))}
            </select>
          </div>
          <div className="input-container">
            <label htmlFor="end-event">End Event:</label>
            <select
              id="end-event"
              value={selectedEndEvent}
              onChange={(e) => setSelectedEndEvent(e.target.value)}
              className="input"
            >
              <option value="">Select end event</option>
              {keyEvents.map(event => (
                <option key={event.date} value={event.date}>
                  {format(parse(event.date, 'yyyy-MM-dd', new Date()), 'MMM dd, yyyy')}: {event.event}
                </option>
              ))}
            </select>
          </div>
        </div>
      )}
    </div>
  );
};

export default RangeTypeSelector;
