export const loadPlotConfig = () => {
  const savedConfig = localStorage.getItem('plotConfig');
  
  if (!savedConfig) {
    return getDefaultConfig();
  }
  
  const config = JSON.parse(savedConfig);
  
  const mergedConfig = {
    ...getDefaultConfig(),
    ...config
  };
  return mergedConfig;
};

export const savePlotConfig = (config) => {
  localStorage.setItem('plotConfig', JSON.stringify(config));
  const saved = localStorage.getItem('plotConfig');
};

export const getDefaultConfig = () => ({
  chartType: 'line',
  daysToShow: 30,
  dateRangeMode: 'lastNDays',
  startDate: '',
  endDate: '',
  selectedStartEvent: '',
  selectedEndEvent: '',
  timeAxisMode: 'linear',
  periodicityK: 7,
  periodicityN: 10,
  yAxisDomain: ['auto', 'auto'],
  yAxisMin: '',
  yAxisMax: '',
  selectedMetric: ''
});
