import React, { useState, useEffect } from 'react';
import { loadDailyMetrics, saveDailyMetrics, computeImputedMetrics } from '../services/metricService';
import { useNavigate } from 'react-router-dom';
import Drawer from './Drawer';
import DatePicker from 'react-datepicker';
import "react-datepicker/dist/react-datepicker.css";
import DateNavigator from './DateNavigator';
import InputBox from './InputBox';

const MetricsLogger = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [metrics, setMetrics] = useState({});
  const [metricDefinitions, setMetricDefinitions] = useState([]);
  const [showKeyEventInput, setShowKeyEventInput] = useState(false);
  const navigate = useNavigate();
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);

  useEffect(() => {
    // Load metric definitions
    const storedMetricDefs = localStorage.getItem('metrics');
    const parsedMetricDefs = storedMetricDefs ? JSON.parse(storedMetricDefs) : [];
    setMetricDefinitions(parsedMetricDefs);

    // Load and compute daily metrics
    const dailyMetrics = loadDailyMetrics(currentDate, parsedMetricDefs);
    setMetrics(dailyMetrics);
    setShowKeyEventInput(!!dailyMetrics.keyEvent);
  }, [currentDate]);

  const handleMetricChange = (metric, value) => {
    const baseMetrics = { ...metrics, [metric]: value };
    const newMetrics = computeImputedMetrics(
      baseMetrics,
      metricDefinitions.filter(m => m.isImputed),
      metricDefinitions,
      []  // Historical data will be loaded in the service
    );
    setMetrics(newMetrics);
    saveDailyMetrics(currentDate, newMetrics);
  };

  const handleKeyEventChange = (event) => {
    const newKeyEvent = event.target.value;
    const newMetrics = { ...metrics, keyEvent: newKeyEvent };
    setMetrics(newMetrics);
    saveDailyMetrics(currentDate, newMetrics);
  };

  const renderInput = (metric) => (
    <InputBox
      key={metric.name}
      label={`${metric.name} (${metric.unit})`}
      value={metrics[metric.name]?.toString() || ''}
      onChange={(e) => handleMetricChange(metric.name, e.target.value ? parseFloat(e.target.value) : null)}
      placeholder={`Enter ${metric.name.toLowerCase()}`}
      type="number"
    />
  );

  return (
    <div className="weight-logger">
      <button 
        className="hamburger-button" 
        onClick={() => setIsDrawerOpen(true)}
      >
        ☰
      </button>
      <Drawer 
        isOpen={isDrawerOpen} 
        onClose={() => setIsDrawerOpen(false)} 
      />
      <div className="date-control">
        <DateNavigator
          currentDate={currentDate}
          onPrevious={() => setCurrentDate(date => new Date(date.getTime() - 86400000))}
          onNext={() => setCurrentDate(date => new Date(date.getTime() + 86400000))}
        >
          <DatePicker
            selected={currentDate}
            onChange={date => setCurrentDate(date)}
            dateFormat="MM/dd/yyyy"
            customInput={
              <div className="date-navigator-text" style={{cursor: 'pointer'}}>
                {currentDate.toLocaleDateString()}
              </div>
            }
          />
        </DateNavigator>
      </div>
      <div className="section">
        <h2 className="section-title">AM</h2>
        {metricDefinitions.filter(metric => metric.timeOfDay === 'AM' && !metric.isImputed).map(renderInput)}
      </div>
      <div className="section">
        <h2 className="section-title">PM</h2>
        {metricDefinitions.filter(metric => metric.timeOfDay === 'PM' && !metric.isImputed).map(renderInput)}
      </div>
      <div className="section">
        <h2 className="section-title">Imputed Metrics</h2>
        {metricDefinitions.filter(metric => metric.isImputed).map(metric => (
          <div key={metric.name} className="imputed-metric">
            <label>{`${metric.name} (${metric.unit})`}</label>
            <div className="imputed-value">
              {typeof metrics[metric.name] === 'number' 
                ? metrics[metric.name].toFixed(2) 
                : 'N/A'}
            </div>
          </div>
        ))}
      </div>
      <div className="section">
        <h2 className="section-title">Notes</h2>
        <InputBox
          label="Notes"
          value={metrics.notes || ''}
          onChange={(e) => handleMetricChange('notes', e.target.value)}
          placeholder="Enter notes for the day"
          type="text"
        />
      </div>
      <div className="section">
        <h2 className="section-title">Key Event</h2>
        {showKeyEventInput ? (
          <InputBox
            label="Key Event"
            value={metrics.keyEvent || ''}
            onChange={handleKeyEventChange}
            placeholder="Enter key event for the day"
            type="text"
          />
        ) : (
          <button onClick={() => setShowKeyEventInput(true)} className="add-key-event-btn">
            Add Key Event
          </button>
        )}
      </div>
      <button onClick={() => navigate('/metrics')} className="manage-metrics-btn">
        Manage Metrics
      </button>
    </div>
  );
};

export default MetricsLogger;
