import React, { useState, useEffect, useRef } from 'react';
import { format, parse, differenceInDays } from 'date-fns';
import { getAllKeyEvents } from '../utils/keyEventUtils';
import { processMetricData, filterDataByDateRange, calculateYAxisDomain, processPeriodicData } from '../utils/plotUtils';
import { loadPlotConfig, savePlotConfig } from '../utils/configUtils';
import Modal from 'react-modal';
import ChartControls from './ChartControls';
import MetricsChart from './MetricsChart';
import RangeTypeSelector from './RangeTypeSelector';

const MetricsPlot = () => {
  const [data, setData] = useState([]);
  const [selectedMetric, setSelectedMetric] = useState('');
  const [chartType, setChartType] = useState('line');
  const [verticalLineX, setVerticalLineX] = useState(null);
  const [tooltipData, setTooltipData] = useState(null);
  const [daysToShow, setDaysToShow] = useState(30);
  const [dateRangeMode, setDateRangeMode] = useState('lastNDays'); // 'lastNDays', 'custom', or 'keyEvents'
  const [keyEvents, setKeyEvents] = useState([]);
  const [selectedStartEvent, setSelectedStartEvent] = useState('');
  const [selectedEndEvent, setSelectedEndEvent] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [metrics, setMetrics] = useState([]);
  const [yAxisMin, setYAxisMin] = useState('');
  const [yAxisMax, setYAxisMax] = useState('');
  const [yAxisDomain, setYAxisDomain] = useState(['auto', 'auto']);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [containerWidth, setContainerWidth] = useState(0);
  const plotContentRef = useRef(null);
  const [timeAxisMode, setTimeAxisMode] = useState('linear'); // 'linear' or 'periodic'
  const [periodicityN, setPeriodicityN] = useState(10); // number of periods
  const [periodicityK, setPeriodicityK] = useState(7); // days per period

  useEffect(() => {
    loadMetrics();
    setKeyEvents(getAllKeyEvents());
    
    const config = loadPlotConfig();
    setChartType(config.chartType);
    setDaysToShow(config.daysToShow);
    setDateRangeMode(config.dateRangeMode);
    setStartDate(config.startDate);
    setEndDate(config.endDate);
    setSelectedStartEvent(config.selectedStartEvent);
    setSelectedEndEvent(config.selectedEndEvent);
    setTimeAxisMode(config.timeAxisMode);
    setPeriodicityK(config.periodicityK);
    setPeriodicityN(config.periodicityN);
    setYAxisDomain(config.yAxisDomain);
    setYAxisMin(config.yAxisMin);
    setYAxisMax(config.yAxisMax);
    if (config.selectedMetric) {
      setSelectedMetric(config.selectedMetric);
    } 
  }, []);

  useEffect(() => {
    if (metrics.length > 0 && !selectedMetric) {
      setSelectedMetric(metrics[0].name);
    }
  }, [metrics]);

  useEffect(() => {
    if (selectedMetric) {
      loadData();
    }
  }, [selectedMetric, daysToShow]);

  const loadMetrics = () => {
    const storedMetrics = localStorage.getItem('metrics');
    if (storedMetrics) {
      setMetrics(JSON.parse(storedMetrics));
    }
  };

  const loadData = () => {
    // Collect all date-based data
    const allData = [];
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key.match(/^\d{4}-\d{2}-\d{2}$/)) {
        const dayData = JSON.parse(localStorage.getItem(key));
        allData.push({ date: key, ...dayData });
      }
    }
    
    // Sort and process data
    let sortedData = allData.sort((a, b) => a.date.localeCompare(b.date));
    const selectedMetricDef = metrics.find(m => m.name === selectedMetric);
    
    // Process metric data (handle imputed metrics)
    sortedData = processMetricData(sortedData, selectedMetric, selectedMetricDef);
    
    // Add periodic information if needed
    let processedData = sortedData.map((item, index) => {
      const value = item[selectedMetric];
      const itemDate = parse(item.date, 'yyyy-MM-dd', new Date());
      const firstDate = parse(sortedData[0].date, 'yyyy-MM-dd', new Date());
      const daysFromStart = differenceInDays(itemDate, firstDate);
      
      const parsedValue = value === null ? null : parseFloat(value);
      return {
        ...item,
        [selectedMetric]: parsedValue,
        periodDay: timeAxisMode === 'periodic' ? (daysFromStart % periodicityK) + 1 : null,
        periodNumber: timeAxisMode === 'periodic' ? Math.floor(daysFromStart / periodicityK) : 0
      };
    }).filter(item => {
      const val = item[selectedMetric];
      return val !== null && 
             !isNaN(val) && 
             isFinite(val) &&
             typeof val === 'number';
    });

    // Handle periodic mode filtering
    if (timeAxisMode === 'periodic') {
      processedData = processPeriodicData(processedData, periodicityK, periodicityN);
    }

    // Filter by date range
    const filteredData = filterDataByDateRange(processedData, dateRangeMode, {
      daysToShow,
      startDate,
      endDate,
      keyEvents,
      selectedStartEvent,
      selectedEndEvent
    });

    setData(filteredData);

    // Update y-axis domain if needed
    if (yAxisDomain[0] === 'auto' || yAxisDomain[1] === 'auto') {
      const newDomain = calculateYAxisDomain(filteredData, selectedMetric, yAxisDomain);
      setYAxisDomain(newDomain);
    }
  };

  const saveCurrentConfig = () => {
    const currentConfig = {
      chartType,
      daysToShow,
      dateRangeMode,
      startDate,
      endDate,
      selectedStartEvent,
      selectedEndEvent,
      timeAxisMode,
      periodicityK,
      periodicityN,
      yAxisDomain,
      yAxisMin,
      yAxisMax,
      selectedMetric
    };
    localStorage.setItem('plotConfig', JSON.stringify(currentConfig));
  };

  const handleMetricChange = (event) => {
    const newMetric = event.target.value;
    setSelectedMetric(newMetric);
    // Reset y-axis to auto when changing metrics
    setYAxisMin('');
    setYAxisMax('');
    setYAxisDomain(['auto', 'auto']);
    
    // Save the selected metric in the config
    const currentConfig = loadPlotConfig();
    const newConfig = {
      ...currentConfig,
      selectedMetric: newMetric
    };
    savePlotConfig(newConfig);
  };

  const handleDaysChange = (event) => {
    const newDays = parseInt(event.target.value, 10);
    setDaysToShow(newDays);
    saveCurrentConfig();
  };

  const handleYAxisMinChange = (event) => {
    setYAxisMin(event.target.value);
  };

  const handleYAxisMaxChange = (event) => {
    setYAxisMax(event.target.value);
  };

  const updateYAxisDomain = () => {
    const newDomain = [
      yAxisMin !== '' ? parseFloat(yAxisMin) : 'auto',
      yAxisMax !== '' ? parseFloat(yAxisMax) : 'auto'
    ];
    setYAxisDomain(newDomain);
  };

  const handleModalClose = () => {
    setIsModalOpen(false);
  };

  const handleApplyChanges = () => {
    const newDomain = [
      yAxisMin !== '' ? parseFloat(yAxisMin) : 'auto',
      yAxisMax !== '' ? parseFloat(yAxisMax) : 'auto'
    ];
    setYAxisDomain(newDomain);
    
    // Save current configuration
    const currentConfig = {
      chartType,
      daysToShow,
      dateRangeMode,
      startDate,
      endDate,
      selectedStartEvent,
      selectedEndEvent,
      timeAxisMode,
      periodicityK,
      periodicityN,
      yAxisDomain: newDomain,
      yAxisMin,
      yAxisMax
    };
    localStorage.setItem('plotConfig', JSON.stringify(currentConfig));
    
    loadData();
    setIsModalOpen(false);
  };

  useEffect(() => {
    if (selectedMetric) {
      loadData();
      saveCurrentConfig();
    }
  }, [selectedMetric, daysToShow, dateRangeMode, startDate, endDate, selectedStartEvent, selectedEndEvent, yAxisDomain, 
      chartType, timeAxisMode, periodicityK, periodicityN]);

  useEffect(() => {
    const updateWidth = () => {
      if (plotContentRef.current) {
        setContainerWidth(plotContentRef.current.clientWidth);
      }
    };

    updateWidth();
    window.addEventListener('resize', updateWidth);
    return () => window.removeEventListener('resize', updateWidth);
  }, []);

  const handleExportToCSV = () => {
    // Collect all date-based data
    const allData = [];
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key.match(/^\d{4}-\d{2}-\d{2}$/)) {
        const dayData = JSON.parse(localStorage.getItem(key));
        allData.push({ date: key, ...dayData });
      }
    }
    
    // Sort data by date
    const sortedData = allData.sort((a, b) => a.date.localeCompare(b.date));
    
    // Create CSV header with all metric names
    const metricNames = new Set();
    sortedData.forEach(day => {
      Object.keys(day).forEach(key => {
        if (key !== 'date') {
          metricNames.add(key);
        }
      });
    });
    
    // Convert to CSV format
    const header = ['Date', ...Array.from(metricNames)];
    const rows = sortedData.map(day => [
      day.date,
      ...Array.from(metricNames).map(metric => day[metric] || '')
    ]);
    
    const csvData = [header, ...rows].map(row => row.join(',')).join('\n');

    const blob = new Blob([csvData], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', 'all_metrics_data.csv');
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const formatXAxis = (tickItem) => {
    const date = data.find(item => item.daysSinceStart === tickItem)?.date;
    return date ? format(parse(date, 'yyyy-MM-dd', new Date()), 'MMM dd') : '';
  };

  return (
    <div className="plot-container">
      <h2 className="section-title">Metrics Plot</h2>
        <ChartControls
          selectedMetric={selectedMetric}
          metrics={metrics}
          chartType={chartType}
          onMetricChange={handleMetricChange}
          onChartTypeChange={(e) => setChartType(e.target.value)}
          onCustomizeClick={() => setIsModalOpen(true)}
          onExportClick={handleExportToCSV}
        />
      <Modal
        isOpen={isModalOpen}
        onRequestClose={handleModalClose}
        contentLabel="Customize Plot"
        className="ReactModal__Content"
        overlayClassName="ReactModal__Overlay"
      >
        <div className="modal-header">
          <h2>Customize Plot</h2>
          <button className="close-button" onClick={handleModalClose}>×</button>
        </div>
        
        <div className="modal-section">
          <h3>Time Axis</h3>
          <div className="range-type-selector">
            <label>
              <input
                type="radio"
                value="linear"
                checked={timeAxisMode === 'linear'}
                onChange={(e) => setTimeAxisMode(e.target.value)}
              />
              Linear Time
            </label>
            <label>
              <input
                type="radio"
                value="periodic"
                checked={timeAxisMode === 'periodic'}
                onChange={(e) => setTimeAxisMode(e.target.value)}
              />
              Periodic Time
            </label>
          </div>

          {timeAxisMode === 'periodic' ? (
            <div className="periodic-controls">
              <div className="input-container">
                <label htmlFor="periodicity-k">Days per Period:</label>
                <input
                  id="periodicity-k"
                  type="number"
                  value={periodicityK}
                  onChange={(e) => setPeriodicityK(parseInt(e.target.value))}
                  min="1"
                  max="365"
                  className="input"
                />
              </div>
              <div className="input-container">
                <label htmlFor="periodicity-n">Number of Periods:</label>
                <input
                  id="periodicity-n"
                  type="number"
                  value={periodicityN}
                  onChange={(e) => setPeriodicityN(parseInt(e.target.value))}
                  min="1"
                  max="52"
                  className="input"
                />
              </div>
            </div>
          ) : (
            <div>
              <RangeTypeSelector
                dateRangeMode={dateRangeMode}
                setDateRangeMode={setDateRangeMode}
                daysToShow={daysToShow}
                handleDaysChange={handleDaysChange}
                startDate={startDate}
                setStartDate={setStartDate}
                endDate={endDate}
                setEndDate={setEndDate}
                keyEvents={keyEvents}
                selectedStartEvent={selectedStartEvent}
                setSelectedStartEvent={setSelectedStartEvent}
                selectedEndEvent={selectedEndEvent}
                setSelectedEndEvent={setSelectedEndEvent}
              />
            </div>
          )}
        </div>

        <div className="modal-section">
          <h3>Y Axis Range</h3>
          <div className="y-axis-controls">
            <div className="input-container">
              <label htmlFor="y-axis-min">Minimum Value:</label>
              <input
                id="y-axis-min"
                type="number"
                value={yAxisMin}
                onChange={handleYAxisMinChange}
                placeholder="Auto"
                className="input"
              />
            </div>
            <div className="input-container">
              <label htmlFor="y-axis-max">Maximum Value:</label>
              <input
                id="y-axis-max"
                type="number"
                value={yAxisMax}
                onChange={handleYAxisMaxChange}
                placeholder="Auto"
                className="input"
              />
            </div>
          </div>
        </div>

        <div className="modal-footer">
          <button className="button apply-button" onClick={handleApplyChanges}>
            Apply Changes
          </button>
          <button className="button" onClick={handleModalClose}>
            Cancel
          </button>
        </div>
      </Modal>
      
        <div className="plot-content" ref={plotContentRef}>
          <MetricsChart
            data={data}
            chartType={chartType}
            selectedMetric={selectedMetric}
            timeAxisMode={timeAxisMode}
            periodicityK={periodicityK}
            periodicityN={periodicityN}
            yAxisDomain={yAxisDomain}
            containerWidth={containerWidth}
          />
        </div>
      </div>
  );
};

export default MetricsPlot;
